{
  "cvars": {
    "ivs": [
      {
        "description": "Binary indicator for whether the player's skin tone is in the dark-skin category as coded by the two raters. Derived by averaging rater1 and rater2, classifying extremes as 'Dark' (average >= 0.6) and 'Light' (average <= 0.4), and keeping only rows in those two groups. This captures the contrast of interest: dark vs light skin tone.",
        "columns": [
          "IsDark"
        ]
      }
    ],
    "dv": {
      "description": "Number of red cards the player received from the referee in the player-referee dyad (count outcome). Modeled with exposure equal to the number of games in the dyad (offset = log(games)).",
      "columns": [
        "redCards"
      ]
    },
    "controls": [
      {
        "description": "Number of games in the player-referee dyad; used as the exposure (offset) in the count model. Kept as a numeric column; must be >= 1.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "games"
        ]
      },
      {
        "description": "Player's age in years at season midpoint (calculated from birthday; reference date 2013-01-01). Controls for age-related differences in play/discipline.",
        "is_moderator": false,
