        ]
      },
      {
        "description": "Number of yellow cards the player received from the referee in the dyad (control for general disciplinary record).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "yellowCards"
        ]
      },
      {
        "description": "Referee-country aggregated implicit bias score (mean IAT) for the referee's country. Controls for country-level implicit bias that might influence refereeing decisions.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "meanIAT"
        ]
      },
      {
        "description": "Referee-country aggregated explicit bias score (mean explicit thermometer difference) for the referee's country. Controls for country-level explicit bias that might influence refereeing decisions.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "meanExp"
        ]
      },
      {
        "description": "Player position on the field (categorical). Included as a factor (dummy variables) in the model to adjust for position-specific red card risk.",
        "is_moderator": false,
